-- Загрузка Rayfield Gen2
local Rayfield = loadstring(game:HttpGet("https://sirius.menu/gen2"))()

-- Создание главного окна
local Window = Rayfield:CreateWindow({
   name = "Roblox Utility Hub",
      subtitle = "CatLua Pro Edition",
         loadingTitle = "Загрузка утилит...",
            loadingSubtitle = "by CatDevs",
               configurationSaving = {
                     enabled = true,
                           folderName = "CatLuaConfigs",
                                 fileName = "MainConfig"
                                    },
                                       keySystem = false,
                                       })

                                       -- Сервисы и игроки
                                       local Players = game:GetService("Players")
                                       local RunService = game:GetService("RunService")
                                       local UserInputService = game:GetService("UserInputService")
                                       local LocalPlayer = Players.LocalPlayer
                                       local Camera = workspace.CurrentCamera

                                       -------------------------------------------------------------------
                                       -- ПЕРЕМЕННЫЕ СОСТОЯНИЙ
                                       -------------------------------------------------------------------
                                       -- AimBot
                                       local AimBotEnabled = false
                                       local AimBotSmoothness = 5
                                       local AimBotFOV = 100
                                       local AimBotTargetPart = "Head"
                                       local AimBotTeamCheck = true
                                       local isAiming = false

                                       -- Camera Bot (AimLock)
                                       local CamBotEnabled = false
                                       local CamBotSpeed = 10
                                       local CamBotTeamCheck = true

                                       -- TriggerBot
                                       local TriggerBotEnabled = false
                                       local TriggerBotDelay = 0.05 -- Задержка перед кликом
                                       local lastTriggerTick = 0

                                       -------------------------------------------------------------------
                                       -- ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
                                       -------------------------------------------------------------------
                                       -- Поиск ближайшего игрока в пределах FOV
                                       local function GetClosestPlayer()
                                          local closestPlayer = nil
                                             local shortestDistance = AimBotFOV

                                                local mouseLocation = UserInputService:GetMouseLocation()

                                                   for _, player in ipairs(Players:GetPlayers()) do
                                                         if player ~= LocalPlayer and player.Character and player.Character:FindFirstChild("Humanoid") and player.Character.Humanoid.Health > 0 then
                                                                  
                                                                           -- TeamCheck
                                                                                    if AimBotTeamCheck and player.Team == LocalPlayer.Team then
                                                                                                continue
                                                                                                         end

                                                                                                                  local targetPart = player.Character:FindFirstChild(AimBotTargetPart) or player.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                           if targetPart then
                                                                                                                                       local screenPoint, onScreen = Camera:WorldToViewportPoint(targetPart.Position)
                                                                                                                                                   if onScreen then
                                                                                                                                                                  local distance = (Vector2.new(screenPoint.X, screenPoint.Y) - mouseLocation).Magnitude
                                                                                                                                                                                 if distance < shortestDistance then
                                                                                                                                                                                                   shortestDistance = distance
                                                                                                                                                                                                                     closestPlayer = player
                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                         end
                                                                                                                                                                                                                                                               end
                                                                                                                                                                                                                                                                  end

                                                                                                                                                                                                                                                                     return closestPlayer
                                                                                                                                                                                                                                                                     end

                                                                                                                                                                                                                                                                     -------------------------------------------------------------------
                                                                                                                                                                                                                                                                     -- ЛОГИКА AIMBOT И TRIGGERBOT (ПОСТОЯННЫЙ СЛЕДУЮЩИЙ ЦИКЛ)
                                                                                                                                                                                                                                                                     -------------------------------------------------------------------
                                                                                                                                                                                                                                                                     RunService.RenderStepped:Connect(function()
                                                                                                                                                                                                                                                                        -- Обработка зажатия ПКМ для AimBot (MouseButton2)
                                                                                                                                                                                                                                                                           isAiming = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)

                                                                                                                                                                                                                                                                              local target = GetClosestPlayer()

                                                                                                                                                                                                                                                                                 -- 1. Camera Bot (AimLock - следит прямо за игроком при включении)
                                                                                                                                                                                                                                                                                    if CamBotEnabled and target and target.Character then
                                                                                                                                                                                                                                                                                          local targetPart = target.Character:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                                                                                                if targetPart then
                                                                                                                                                                                                                                                                                                         local teamValid = not CamBotTeamCheck or (target.Team ~= LocalPlayer.Team)
                                                                                                                                                                                                                                                                                                                  if teamValid then
                                                                                                                                                                                                                                                                                                                              local goalCFrame = CFrame.new(Camera.CFrame.Position, targetPart.Position)
                                                                                                                                                                                                                                                                                                                                          Camera.CFrame = Camera.CFrame:Lerp(goalCFrame, CamBotSpeed / 20)
                                                                                                                                                                                                                                                                                                                                                   end
                                                                                                                                                                                                                                                                                                                                                         end
                                                                                                                                                                                                                                                                                                                                                            end

                                                                                                                                                                                                                                                                                                                                                               -- 2. AimBot (срабатывает по зажатию кнопки мыши)
                                                                                                                                                                                                                                                                                                                                                                  if AimBotEnabled and isAiming and target and target.Character then
                                                                                                                                                                                                                                                                                                                                                                        local targetPart = target.Character:FindFirstChild(AimBotTargetPart)
                                                                                                                                                                                                                                                                                                                                                                              if targetPart then
                                                                                                                                                                                                                                                                                                                                                                                       local screenPoint = Camera:WorldToViewportPoint(targetPart.Position)
                                                                                                                                                                                                                                                                                                                                                                                                local mouseLocation = UserInputService:GetMouseLocation()
                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                  -- Плавное смещение мыши к цели
                                                                                                                                                                                                                                                                                                                                                                                                                           local moveX = (screenPoint.X - mouseLocation.X) / AimBotSmoothness
                                                                                                                                                                                                                                                                                                                                                                                                                                    local moveY = (screenPoint.Y - mouseLocation.Y) / AimBotSmoothness
                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                      mousemoverel(moveX, moveY) -- Встроенная функция эксекутора для движения мыши
                                                                                                                                                                                                                                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                                                                                                                                                                                                                                               end

                                                                                                                                                                                                                                                                                                                                                                                                                                                                  -- 3. TriggerBot (Автоматический выстрел/клик при наведении на врага)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if TriggerBotEnabled and target and target.Character then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           local targetPart = target.Character:FindFirstChild(AimBotTargetPart)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if targetPart then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          local screenPoint, onScreen = Camera:WorldToViewportPoint(targetPart.Position)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   local mouseLocation = UserInputService:GetMouseLocation()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            local distance = (Vector2.new(screenPoint.X, screenPoint.Y) - mouseLocation).Magnitude
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              -- Если прицел очень близко к цели (внутри микро-зоны 15 пикселей)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if onScreen and distance < 15 then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if tick() - lastTriggerTick > TriggerBotDelay then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  lastTriggerTick = tick()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 -- Эмуляция клика мыши
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mouse1click()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              end)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              -------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              -- ВКЛАДКА: AIMBOT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              -------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              local AimBotTab = Window:CreateTab({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 name = "AimBot",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    icon = 4483362458
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    AimBotTab:CreateSection("Настройки AimBot (Работает по зажатию ПКМ)")

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    AimBotTab:CreateToggle({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       name = "Включить AimBot",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          currentValue = false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             flag = "AimBot_Enabled",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      AimBotEnabled = value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         AimBotTab:CreateSlider({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            name = "Плавность (Smoothness)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               range = {1, 20},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  increment = 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     currentValue = 5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        flag = "AimBot_Smoothness",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 AimBotSmoothness = value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    AimBotTab:CreateSlider({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       name = "Радиус FOV",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          range = {10, 300},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             increment = 5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                currentValue = 100,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   flag = "AimBot_FOV",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            AimBotFOV = value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               AimBotTab:CreateDropdown({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  name = "Часть тела",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     options = {"Head", "HumanoidRootPart"},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        currentOption = "Head",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           flag = "AimBot_Part",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              callback = function(option)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    AimBotTargetPart = option
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       AimBotTab:CreateToggle({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          name = "Проверка команд (TeamCheck)",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             currentValue = true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                flag = "AimBot_TeamCheck",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   callback = function(value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         AimBotTeamCheck = value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -------------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -- ВКЛАДКА: CAMERA BOT (AimLock / Слежка за игроком)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -------------------------------------------------------------------
